optimizedSolution.code:
function rotateOne(nums) {
  if (nums.length <= 1) return nums;
  const temp = nums[0];
  for (let i = 0; i < nums.length - 1; i++) {
    nums[i] = nums[i + 1];
  }
  nums[nums.length - 1] = temp;
  return nums;
}
